<?php
require __DIR__.'/oyunchu_config.php';
$msg=''; $err='';
try { $conn->query("CREATE TABLE IF NOT EXISTS es_quiz_questions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, question_az TEXT NOT NULL, option_a VARCHAR(255) NOT NULL, option_b VARCHAR(255) NOT NULL, option_c VARCHAR(255) NOT NULL, option_d VARCHAR(255) NOT NULL, correct_option CHAR(1) NOT NULL, category VARCHAR(60) DEFAULT 'ümumi', difficulty TINYINT DEFAULT 1, points SMALLINT DEFAULT 10, is_active TINYINT(1) DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"); } catch(Throwable $e){}
try { $conn->query("ALTER TABLE es_quiz_questions ADD COLUMN game_slug VARCHAR(30) DEFAULT NULL"); } catch(Throwable $e) {}
$games=$conn->query("SELECT slug,default_name,default_logo,is_active FROM oh_games ORDER BY sort_order,id")->fetch_all(MYSQLI_ASSOC);
$valid=array_column($games,'slug');
if($_SERVER['REQUEST_METHOD']==='POST'){
  ga_verify(); $action=$_POST['action']??'';
  if($action==='assign'){
    $slug=$_POST['game_slug']??''; $ids=array_values(array_filter(array_map('intval',$_POST['ids']??[])));
    if($slug!=='' && $slug!=='shared' && !in_array($slug,$valid,true)) $err='Yanlış oyun seçilib.';
    elseif(!$ids) $err='Ən azı bir sual seçin.';
    else { $val=($slug==='shared')?null:$slug; $q=$conn->prepare('UPDATE es_quiz_questions SET game_slug=? WHERE id=?'); foreach($ids as $id){$q->bind_param('si',$val,$id);$q->execute();} ga_audit('oyunchu_question_assign','es_quiz_questions',null,count($ids).' sual -> '.($slug==='shared'?'ortaq':$slug)); $msg=count($ids).' sual yeniləndi.'; }
  } elseif($action==='toggle') { $id=(int)$_POST['id']; $q=$conn->prepare('UPDATE es_quiz_questions SET is_active=1-is_active WHERE id=?');$q->bind_param('i',$id);$q->execute();$msg='Sual statusu dəyişdirildi.';ga_audit('oyunchu_question_toggle','es_quiz_questions',$id); }
  elseif($action==='delete') { $id=(int)$_POST['id'];$q=$conn->prepare('DELETE FROM es_quiz_questions WHERE id=?');$q->bind_param('i',$id);$q->execute();$msg='Sual silindi.';ga_audit('oyunchu_question_delete','es_quiz_questions',$id); }
}
$filter=$_GET['game']??''; $status=$_GET['status']??'all'; $search=trim($_GET['q']??'');
$where=['1=1']; $types='';$params=[];
if($filter==='shared'){ $where[]='(q.game_slug IS NULL OR q.game_slug="")'; }
elseif(in_array($filter,$valid,true)){ $where[]='q.game_slug=?';$types.='s';$params[]=$filter; }
if($status==='active'){ $where[]='q.is_active=1'; } elseif($status==='inactive'){ $where[]='q.is_active=0'; }
if($search!==''){ $where[]='(q.question_az LIKE ? OR q.category LIKE ?)';$types.='ss';$like='%'.$search.'%';$params[]=$like;$params[]=$like; }
$sql="SELECT q.id,q.question_az,q.category,q.difficulty,q.points,q.is_active,q.game_slug,q.created_at FROM es_quiz_questions q WHERE ".implode(' AND ',$where)." ORDER BY q.id DESC LIMIT 250";
$stmt=$conn->prepare($sql); if($types)$stmt->bind_param($types,...$params); $stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="az" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sual bankı — Oyun inteqrasiyası</title><script>document.documentElement.setAttribute('data-theme',localStorage.getItem('esevgili_theme')||'dark');</script></head><body><?php include __DIR__.'/oyunchu_sidebar.php';?><main class="ga-main"><div class="ga-top"><b>❓ Sual bankı — oyun inteqrasiyası</b><a class="ga-btn ga-mutedbtn" href="/telesmartadmin/oyunchu/oyunchu_sual_questions.php">Tam sual redaktoru</a></div><div class="ga-content"><?php if($msg):?><div class="ga-alert"><?=ga_h($msg)?></div><?php endif;?><?php if($err):?><div class="ga-alert err"><?=ga_h($err)?></div><?php endif;?><div class="ga-card"><p class="ga-muted">Ortaq suallar bütün uyğun oyunlarda görünür. Konkret oyun seçsəniz, həmin sual yalnız o oyunda istifadə olunur.</p><form method="get" class="ga-form"><div><label class="ga-label">Oyun</label><select class="ga-input" name="game"><option value="">Bütün oyunlar</option><option value="shared" <?=$filter==='shared'?'selected':''?>>Ortaq / təyin edilməyib</option><?php foreach($games as $g):?><option value="<?=ga_h($g['slug'])?>" <?=$filter===$g['slug']?'selected':''?>><?=ga_h($g['default_logo'].' '.$g['default_name'])?></option><?php endforeach;?></select></div><div><label class="ga-label">Status</label><select class="ga-input" name="status"><option value="all">Hamısı</option><option value="active" <?=$status==='active'?'selected':''?>>Aktiv</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Passiv</option></select></div><div><label class="ga-label">Axtarış</label><input class="ga-input" name="q" value="<?=ga_h($search)?>" placeholder="Sual və ya kateqoriya"></div><div style="padding-top:24px"><button class="ga-btn ga-primary">Filtrlə</button></div></form></div><br><form method="post"><?php echo csrf_field();?><input type="hidden" name="action" value="assign"><div class="ga-card"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><select class="ga-input" style="max-width:300px" name="game_slug" required><option value="">Seçilmiş sualları hara bağla?</option><option value="shared">Ortaq bütün oyunlar</option><?php foreach($games as $g):?><option value="<?=ga_h($g['slug'])?>"><?=ga_h($g['default_logo'].' '.$g['default_name'])?></option><?php endforeach;?></select><button class="ga-btn ga-primary">Seçilənləri bağla</button><label class="ga-muted"><input type="checkbox" onclick="document.querySelectorAll('.qid').forEach(x=>x.checked=this.checked)"> Hamısını seç</label></div></div><br><div class="ga-card"><div style="overflow:auto"><table class="ga-table"><tr><th></th><th>ID</th><th>Sual</th><th>Kateqoriya</th><th>Çətinlik</th><th>Bal</th><th>Oyun</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><input class="qid" type="checkbox" name="ids[]" value="<?=$r['id']?>"></td><td>#<?=$r['id']?></td><td><?=ga_h(mb_strimwidth($r['question_az'],0,100,'…','UTF-8'))?></td><td><?=ga_h($r['category'])?></td><td><?=$r['difficulty']?></td><td><?=$r['points']?></td><td><?php if($r['game_slug']):?><b><?=ga_h($r['game_slug'])?></b><?php else:?>🌐 Ortaq<?php endif;?></td><td><?=$r['is_active']?'🟢 Aktiv':'🔴 Passiv'?></td><td><a class="ga-btn ga-mutedbtn" href="/telesmartadmin/oyunchu/oyunchu_sual_questions.php?edit=<?=$r['id']?>">Redaktə</a></td></tr><?php endforeach;?></table></div></div></form></div></main></body></html>
